/**
 * The N/dataStore module stores internal application data as JSON objects, called documents, without requiring custom records.
 * You can also retrieve, update, and delete these documents. Each document is stored in a collection within a data store.
 *
 * Use dataStore.getDatastore(id) to get a data store, then Datastore.getCollection(id) to get a collection.
 * The methods of a collection return Promises, so use await or then().
 * The default data store has the identifier 'default', and dataStore.getCollection(id) is the same as dataStore.getDatastore('default').getCollection(id).
 *
 * Data is stored in the executing script's storage scope:
 * - Account scope: scripts that don't belong to a SuiteApp share data.
 * - SuiteApp scope: scripts in the same SuiteApp share data, kept apart from account data and from other SuiteApps.
 *
 * Restrictions:
 * - Don't use this module to store sensitive information.
 * - It isn't supported in scripts installed through SuiteBundler. To migrate, use Account Customization Projects or Copy to Account.
 *
 * Supported in server scripts only, with SuiteScript 2.1.
 * @since 2026.2
 */

/**
 * A value that can be stored in a document and that is returned when a document is read.
 *
 * Numbers must be finite, and either 0 or have an absolute value of at least 1e-130 and less than 1e126.
 * Functions aren't allowed. NetSuite also accepts JavaScript Date values, but stores them as UTC ISO 8601 strings
 * and returns strings when the document is read, so pass `date.toISOString()` instead.
 * @since 2026.2
 */
export type DocumentValue = string | number | boolean | null | DocumentValue[] | { [property: string]: DocumentValue };

/**
 * The default type of a document's properties, used when getCollection() is called without a type argument.
 *
 * Property names must be nonempty, can't contain dots or start with `$`, and can't be `__proto__`, `constructor` or `prototype`, including in nested objects.
 * The normalized JSON body of a document, excluding `_id`, must not exceed 10 MB (10,485,760 bytes) when encoded as UTF-8.
 * @since 2026.2
 */
export type DocumentData = { [property: string]: DocumentValue };

/**
 * A JSON object representing a stored document: your properties plus the system-generated `_id`.
 * @since 2026.2
 */
export type Document<T extends object = DocumentData> = T & {
  /**
   * The system-generated document identifier. Use it in queries to identify the document.
   * It can't be changed through an update.
   * @since 2026.2
   */
  readonly _id: string;
};

/**
 * A document to insert. `_id` is generated by NetSuite, so a top-level `_id` property isn't allowed.
 * An empty object is valid.
 * @since 2026.2
 */
export type NewDocument<T extends object = DocumentData> = T & { _id?: never };

/**
 * A JSON scalar value used in a query comparison. Objects and arrays can't be compared as whole values.
 *
 * Comparisons require matching types, so the string `'5'` doesn't match the number `5`. String comparisons are case-sensitive.
 * Strings are limited to 4,000 bytes when encoded as UTF-8. Numbers must be finite, and either 0 or have an absolute value of at least 1e-130 and less than 1e126.
 * Dates are stored as UTC ISO 8601 strings, so query them as strings.
 * @since 2026.2
 */
export type QueryValue = string | number | boolean | null;

/**
 * Conditions on a single field, such as `{ $gte: 0, $lt: 3 }`. If several operators are given, every condition must be satisfied.
 * An operator object must contain at least one operator. Other operators aren't supported.
 * @since 2026.2
 */
export interface FieldCondition {
  /**
   * Matches the field against the value. Assigning the value directly to the field property, such as `{ score: 20 }`, is shorthand for `$eq`.
   * @since 2026.2
   */
  $eq?: QueryValue;
  /**
   * Matches existing field values of the same data type that differ from the value, so `{ score: { $ne: 20 } }` matches `10`, but not `'10'` or null.
   * A condition using `$ne: null` doesn't match any field value.
   * @since 2026.2
   */
  $ne?: QueryValue;
  /**
   * Matches values greater than the value.
   * @since 2026.2
   */
  $gt?: number | string;
  /**
   * Matches values greater than or equal to the value.
   * @since 2026.2
   */
  $gte?: number | string;
  /**
   * Matches values less than the value.
   * @since 2026.2
   */
  $lt?: number | string;
  /**
   * Matches values less than or equal to the value.
   * @since 2026.2
   */
  $lte?: number | string;
  /**
   * Matches when the field's value equals one of the values. If the field contains an array, matches when at least one element equals one of the values.
   * The array must contain 1 to 100 values.
   * @since 2026.2
   */
  $in?: QueryValue[];
  /**
   * `true` matches documents that have the field, including when its value is null.
   * `false` matches documents that don't have the field.
   * @since 2026.2
   */
  $exists?: boolean;
  /**
   * Matches documents whose array field has an element that satisfies every condition, such as `{ numbers: { $elemMatch: { $gt: 5, $lt: 15 } } }`.
   * The same array element must satisfy all the conditions. You can't nest `$elemMatch` within another `$elemMatch`.
   * @since 2026.2
   */
  $elemMatch?: Query | FieldCondition;
}

/**
 * Selects documents for Collection.find(query), findOne(query), updateOne(query, update), updateMany(query, update), deleteOne(query) and deleteMany(query).
 *
 * - `{ field: value }` matches documents where the field equals the value.
 * - `{ field: { $operator: value } }` applies a field condition (see FieldCondition).
 * - `{ $and: [query, ...] }` and `{ $or: [query, ...] }` combine queries. The arrays must be nonempty.
 *
 * Multiple properties are combined with AND. Use dot notation for nested properties, such as `'profile.country'`.
 * Field paths are limited to 32 segments and 256 bytes; array indexes and JSONPath syntax aren't supported.
 * A query can contain at most 300 operators, including implicit comparisons and logical connectors.
 * An empty query object matches all documents in the collection.
 * @since 2026.2
 */
export interface Query {
  /** Matches documents that match every query in the array. */
  $and?: Query[];
  /** Matches documents that match at least one query in the array. */
  $or?: Query[];
  [fieldPath: string]: QueryValue | FieldCondition | Query[] | undefined;
}

/**
 * Specifies changes to top-level properties for Collection.updateOne(query, update) and Collection.updateMany(query, update).
 *
 * Provide at least one operator, each with at least one property. Each property can be targeted by only one operator.
 * The top-level `_id` property can't be updated. Only `$set`, `$unset` and `$inc` are supported.
 *
 * If an update fails because of an invalid increment target, an out-of-range numeric result, or an oversized resulting document, the entire update is rolled back.
 * @since 2026.2
 */
export interface Update<T extends object = DocumentData> {
  /**
   * Sets each property to the given value. If the value is an object, it replaces the entire existing object.
   * @since 2026.2
   */
  $set?: Partial<Omit<T, '_id'>> & { _id?: never };
  /**
   * Removes each property from the document. Missing properties are ignored. The values aren't used, so `true` is conventional.
   * @since 2026.2
   */
  $unset?: { [K in Exclude<keyof T, '_id'>]?: DocumentValue } & { _id?: never };
  /**
   * Adds the given number to each property, or subtracts it if it's negative. The property must already exist and contain a number.
   * Retrying an update that uses `$inc` could apply the increment twice.
   * @since 2026.2
   */
  $inc?: { [K in keyof T as number extends T[K] ? Exclude<K, '_id'> : never]?: number } & { _id?: never };
}

/**
 * Contains information about the document: its size in bytes and its version. The API manages these values.
 * @since 2026.2
 */
export interface DocumentMetadata {
  /**
   * The size of the normalized JSON document body in bytes, after UTF-8 encoding. It excludes `_id`.
   * @since 2026.2
   */
  readonly byteLength: number;
  /**
   * The stored document's version number. It starts at `'1'` and the API increments it on each update.
   * @since 2026.2
   */
  readonly version: string;
}

/**
 * Contains a matching document and its metadata. Returned for each match when iterating a dataStore.Cursor.
 * @since 2026.2
 */
export interface FindResult<T extends object = DocumentData> {
  /**
   * The document that matches the query.
   * @since 2026.2
   */
  readonly document: Document<T>;
  /**
   * The matching document's metadata.
   * @since 2026.2
   */
  readonly metadata: DocumentMetadata;
}

/**
 * Contains a matching document and its metadata. Returned by Collection.findOne(query).
 * When no document matches, both properties are null, so check `result.document !== null`.
 * @since 2026.2
 */
export type FindOneResult<T extends object = DocumentData> = FindResult<T> | {
  readonly document: null;
  readonly metadata: null;
};

/**
 * Contains an inserted document's generated identifier and metadata.
 * Returned by Collection.insertOne(document), and included in InsertManyResult.inserted.
 * @since 2026.2
 */
export interface InsertOneResult {
  /**
   * The inserted document's generated `_id` value.
   * @since 2026.2
   */
  readonly insertedId: string;
  /**
   * The inserted document's metadata.
   * @since 2026.2
   */
  readonly metadata: DocumentMetadata;
}

/**
 * Contains the number of documents inserted and the insertion result for each document. Returned by Collection.insertMany(documents).
 * @since 2026.2
 */
export interface InsertManyResult {
  /**
   * The result for each inserted document, in the order of the input documents. Empty when the input array is empty.
   * @since 2026.2
   */
  readonly inserted: InsertOneResult[];
  /**
   * The number of documents inserted. 0 when the input array is empty.
   * @since 2026.2
   */
  readonly insertedCount: number;
}

/**
 * Contains the number of documents updated. Returned by Collection.updateOne(query, update) and Collection.updateMany(query, update).
 * @since 2026.2
 */
export interface UpdateResult {
  /**
   * The number of documents updated. 0 when no document matches.
   * @since 2026.2
   */
  readonly updatedCount: number;
}

/**
 * Contains the number of documents deleted. Returned by Collection.deleteOne(query) and Collection.deleteMany(query).
 * @since 2026.2
 */
export interface DeleteResult {
  /**
   * The number of documents deleted. 0 when no document matches.
   * @since 2026.2
   */
  readonly deletedCount: number;
}

/**
 * An asynchronous iterator for the documents retrieved by Collection.find(query). Use it with `for await...of`.
 *
 * Results are retrieved in groups of up to 100 documents, with a combined document body size of up to 10 MB per group.
 * Changes to stored documents during retrieval can affect later results.
 * @since 2026.2
 */
export interface Cursor<T extends object = DocumentData> extends AsyncIterable<FindResult<T>> {
  /**
   * Returns the next iterator result. When a result is available, its `value` property contains a dataStore.FindResult object.
   * Retrieves more results as needed. Calls made before an earlier call finishes are processed in order.
   * A failure while retrieving more results closes the cursor and rejects the Promise.
   * @governance 10 units for each retrieval request, none for calls that don't need one
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if a circular reference is found while retrieving more results.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_QUERY if the query is invalid.
   * @throws {SuiteScriptError} DATA_STORE_TOO_MANY_PARAMETERS if the operation requires more than 32,000 bound parameters.
   * @since 2026.2
   */
  next(): Promise<IteratorResult<FindResult<T>, undefined>>;
  /**
   * Closes the cursor and ends iteration. Later calls to next() report that iteration is complete.
   * Exiting a `for await...of` loop early, such as with `break`, calls this method automatically.
   * @governance none
   * @since 2026.2
   */
  return(): Promise<IteratorReturnResult<undefined>>;
}

/**
 * A collection of documents within a data store. Use its methods to insert, retrieve, update, and delete documents.
 * Returned by dataStore.getCollection(id) and Datastore.getCollection(id).
 *
 * Each call saves its changes independently: changes saved by one call aren't rolled back if a later call fails.
 * insertMany, updateMany and deleteMany save or roll back all their changes together, and don't return partial-success results.
 *
 * If a write fails with DATA_STORE_OUTCOME_UNKNOWN, its changes may have been saved: check before retrying.
 * If it fails with DATA_STORE_COMMITTED_RESULT_UNAVAILABLE, its changes were saved but the result couldn't be returned: don't retry.
 * @since 2026.2
 */
export interface Collection<T extends object = DocumentData> {
  /**
   * Finds all documents that match the query. Results are ordered by `_id`.
   * @param query The query. An empty object matches all documents.
   * @governance 10 units for the initial retrieval
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_QUERY if the query is invalid.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if the query contains a function or a circular reference.
   * @throws {SuiteScriptError} DATA_STORE_TOO_MANY_PARAMETERS if the operation requires more than 32,000 bound parameters.
   * @since 2026.2
   */
  find(query: Query): Promise<Cursor<T>>;
  /**
   * Finds the first document that matches the query. Matching documents are ordered by `_id` in ascending order.
   * When no document matches, the result's document and metadata are null.
   * @param query The query. An empty object matches all documents.
   * @governance 2 units
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_QUERY if the query is invalid.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if the query contains a function or a circular reference.
   * @throws {SuiteScriptError} DATA_STORE_TOO_MANY_PARAMETERS if the operation requires more than 32,000 bound parameters.
   * @since 2026.2
   */
  findOne(query: Query): Promise<FindOneResult<T>>;
  /**
   * Inserts one document and generates its `_id`. The generated `_id` isn't added to the input document.
   * @param document The document to insert. An empty object is valid. Don't include a top-level `_id`.
   * @governance 2 units
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if the document is invalid, such as including `_id`, a function, a circular reference, an invalid property name or an out-of-range number.
   * @throws {SuiteScriptError} DATA_STORE_DOCUMENT_TOO_LARGE if the document body exceeds 10 MB.
   * @throws {SuiteScriptError} DATA_STORE_DUPLICATE_DOCUMENT if a document with the same identifier already exists. The insert is rolled back.
   * @throws {SuiteScriptError} DATA_STORE_OUTCOME_UNKNOWN if the operation may have been saved. Don't retry automatically.
   * @throws {SuiteScriptError} DATA_STORE_COMMITTED_RESULT_UNAVAILABLE if the operation was saved but its result couldn't be returned. Don't retry.
   * @since 2026.2
   */
  insertOne(document: NewDocument<T>): Promise<InsertOneResult>;
  /**
   * Inserts multiple documents and generates an `_id` for each document. Results follow the input order.
   * An empty array is accepted and inserts no documents.
   * @param documents The documents to insert. Each can be an empty object. Don't include a top-level `_id` in any document. Their combined bodies must not exceed 10 MB.
   * @governance 10 units
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if a document is invalid, such as including `_id`, a function, a circular reference, an invalid property name or an out-of-range number.
   * @throws {SuiteScriptError} DATA_STORE_DOCUMENT_TOO_LARGE if a document body exceeds 10 MB.
   * @throws {SuiteScriptError} DATA_STORE_BATCH_TOO_LARGE if the combined document bodies exceed 10 MB. Split the documents into smaller batches.
   * @throws {SuiteScriptError} DATA_STORE_DUPLICATE_DOCUMENT if a document with the same identifier already exists. The insert is rolled back.
   * @throws {SuiteScriptError} DATA_STORE_OUTCOME_UNKNOWN if the operation may have been saved. Don't retry automatically.
   * @throws {SuiteScriptError} DATA_STORE_COMMITTED_RESULT_UNAVAILABLE if the operation was saved but its result couldn't be returned. Don't retry.
   * @since 2026.2
   */
  insertMany(documents: NewDocument<T>[]): Promise<InsertManyResult>;
  /**
   * Updates the first document that matches the query. Matching documents are ordered by `_id` in ascending order.
   * Doesn't update a document if no document matches.
   * @param query The query. An empty object matches all documents.
   * @param update The changes to apply.
   * @governance 2 units
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_QUERY if the query is invalid.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_UPDATE if the update is invalid, such as targeting `_id`, targeting a property twice, or using `$inc` on a missing or non-numeric property.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if the query or update contains a function or a circular reference.
   * @throws {SuiteScriptError} DATA_STORE_NUMBER_OUT_OF_RANGE if an `$inc` result is outside the supported numeric range. The update is rolled back.
   * @throws {SuiteScriptError} DATA_STORE_DOCUMENT_TOO_LARGE if the resulting document body exceeds 10 MB.
   * @throws {SuiteScriptError} DATA_STORE_TOO_MANY_PARAMETERS if the operation requires more than 32,000 bound parameters.
   * @throws {SuiteScriptError} DATA_STORE_LOCK_TIMEOUT if the operation timed out waiting for a document lock. The update is rolled back; try again later.
   * @throws {SuiteScriptError} DATA_STORE_OUTCOME_UNKNOWN if the operation may have been saved. Don't retry automatically.
   * @throws {SuiteScriptError} DATA_STORE_COMMITTED_RESULT_UNAVAILABLE if the operation was saved but its result couldn't be returned. Don't retry.
   * @since 2026.2
   */
  updateOne(query: Query, update: Update<T>): Promise<UpdateResult>;
  /**
   * Updates all documents that match the query. Each resulting document body must not exceed 10 MB.
   * Doesn't update documents if no documents match.
   * @param query The query. An empty object matches all documents.
   * @param update The changes to apply.
   * @governance 10 units
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_QUERY if the query is invalid.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_UPDATE if the update is invalid, such as targeting `_id`, targeting a property twice, or using `$inc` on a missing or non-numeric property.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if the query or update contains a function or a circular reference.
   * @throws {SuiteScriptError} DATA_STORE_NUMBER_OUT_OF_RANGE if an `$inc` result is outside the supported numeric range. The update is rolled back.
   * @throws {SuiteScriptError} DATA_STORE_DOCUMENT_TOO_LARGE if a resulting document body exceeds 10 MB.
   * @throws {SuiteScriptError} DATA_STORE_TOO_MANY_PARAMETERS if the operation requires more than 32,000 bound parameters.
   * @throws {SuiteScriptError} DATA_STORE_LOCK_TIMEOUT if the operation timed out waiting for a document lock. The update is rolled back; try again later.
   * @throws {SuiteScriptError} DATA_STORE_OUTCOME_UNKNOWN if the operation may have been saved. Don't retry automatically.
   * @throws {SuiteScriptError} DATA_STORE_COMMITTED_RESULT_UNAVAILABLE if the operation was saved but its result couldn't be returned. Don't retry.
   * @since 2026.2
   */
  updateMany(query: Query, update: Update<T>): Promise<UpdateResult>;
  /**
   * Deletes the first document that matches the query. Matching documents are ordered by `_id` in ascending order.
   * @param query The query. An empty object matches all documents.
   * @governance 2 units
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_QUERY if the query is invalid.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if the query contains a function or a circular reference.
   * @throws {SuiteScriptError} DATA_STORE_TOO_MANY_PARAMETERS if the operation requires more than 32,000 bound parameters.
   * @throws {SuiteScriptError} DATA_STORE_LOCK_TIMEOUT if the operation timed out waiting for a document lock. Try again later.
   * @throws {SuiteScriptError} DATA_STORE_OUTCOME_UNKNOWN if the operation may have been saved. Don't retry automatically.
   * @throws {SuiteScriptError} DATA_STORE_COMMITTED_RESULT_UNAVAILABLE if the operation was saved but its result couldn't be returned. Don't retry.
   * @since 2026.2
   */
  deleteOne(query: Query): Promise<DeleteResult>;
  /**
   * Deletes all documents that match the query. An empty query object (`{}`) deletes all documents in the collection.
   * @param query The query.
   * @governance 10 units
   * @throws {SuiteScriptError} DATA_STORE_NOT_ENABLED if the N/dataStore API isn't enabled for this account.
   * @throws {SuiteScriptError} DATA_STORE_BUNDLE_NOT_SUPPORTED if the script belongs to a bundle.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_QUERY if the query is invalid.
   * @throws {SuiteScriptError} DATA_STORE_INVALID_DOCUMENT if the query contains a function or a circular reference.
   * @throws {SuiteScriptError} DATA_STORE_TOO_MANY_PARAMETERS if the operation requires more than 32,000 bound parameters.
   * @throws {SuiteScriptError} DATA_STORE_LOCK_TIMEOUT if the operation timed out waiting for a document lock. Try again later.
   * @throws {SuiteScriptError} DATA_STORE_OUTCOME_UNKNOWN if the operation may have been saved. Don't retry automatically.
   * @throws {SuiteScriptError} DATA_STORE_COMMITTED_RESULT_UNAVAILABLE if the operation was saved but its result couldn't be returned. Don't retry.
   * @since 2026.2
   */
  deleteMany(query: Query): Promise<DeleteResult>;
}

/**
 * A data store containing collections of documents. Returned by dataStore.getDatastore(id).
 * @since 2026.2
 */
export interface Datastore {
  /**
   * Returns a dataStore.Collection object for the specified collection in this data store.
   * This method doesn't read or write stored documents.
   *
   * Pass a type argument to describe the collection's documents, such as `getCollection<Checkpoint>('checkpoints')`.
   * NetSuite doesn't check stored documents against it.
   * @param id The identifier of the collection: 1-64 ASCII letters, digits, underscores, dots, or hyphens. Case-insensitive.
   * @governance none
   * @throws {TypeError} if the identifier isn't a string with 1 to 64 ASCII letters, digits, underscores, dots, or hyphens.
   * @since 2026.2
   */
  getCollection<T extends object = DocumentData>(id: string): Collection<T>;
}

/**
 * Returns a dataStore.Datastore object for the specified data store in the executing script's storage scope.
 * This method doesn't read or write stored documents.
 * @param id The identifier of the data store: 1-64 ASCII letters, digits, underscores, dots, or hyphens. Case-insensitive. The default data store is 'default'.
 * @governance none
 * @throws {TypeError} if the identifier isn't a string with 1 to 64 ASCII letters, digits, underscores, dots, or hyphens.
 * @since 2026.2
 */
export function getDatastore(id: string): Datastore;

/**
 * Returns a dataStore.Collection object for the specified collection in the default data store.
 * The same as dataStore.getDatastore('default').getCollection(id). This method doesn't read or write stored documents.
 *
 * Pass a type argument to describe the collection's documents, such as `getCollection<Checkpoint>('checkpoints')`.
 * NetSuite doesn't check stored documents against it.
 * @param id The identifier of the collection: 1-64 ASCII letters, digits, underscores, dots, or hyphens. Case-insensitive.
 * @governance none
 * @throws {TypeError} if the identifier isn't a string with 1 to 64 ASCII letters, digits, underscores, dots, or hyphens.
 * @since 2026.2
 */
export function getCollection<T extends object = DocumentData>(id: string): Collection<T>;
